import{_ as t,o as a,c as r,ah as d}from"./chunks/framework.ChH6X6u6.js";const p=JSON.parse('{"title":"The parent portal","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/parent/index.md","filePath":"src/en/guide/parent/index.md"}'),n={name:"en/guide/parent/index.md"};function o(i,e,s,h,c,l){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="the-parent-portal" tabindex="-1">The parent portal <a class="header-anchor" href="#the-parent-portal" aria-label="Permalink to &quot;The parent portal&quot;">​</a></h1><p>As a parent or guardian, you have a dedicated space to follow your children&#39;s schooling: grades, attendance, documents to download, payments and requests. Once signed in, you land on the <strong>My children</strong> page, which shows one card per child linked to your account: their class, absences to justify, next installment, average, balance and latest grades. Click a card to open that child&#39;s full record.</p><p>This guide covers the three things you can do from this portal:</p><table tabindex="0"><thead><tr><th>Page</th><th>What you can do there</th></tr></thead><tbody><tr><td><a href="/era-guide/en/guide/parent/enfants-et-documents.html">Your children and their documents</a></td><td>See your children, follow their record (grades, attendance, discipline) and download their report cards, receipts, disciplinary-council minutes and lesson-log attachments; export their timetable</td></tr><tr><td><a href="/era-guide/en/guide/parent/paiements-en-ligne.html">Online payments</a></td><td>Track school fees and pay directly online by mobile money</td></tr><tr><td><a href="/era-guide/en/guide/parent/demarches.html">Requests</a></td><td>Justify a child&#39;s absence or request a site transfer</td></tr></tbody></table><h2 id="what-you-are-told-about" tabindex="-1">What you are told about <a class="header-anchor" href="#what-you-are-told-about" aria-label="Permalink to &quot;What you are told about&quot;">​</a></h2><p>The school tells you, by email and in the notification bell of your space, in these cases:</p><table tabindex="0"><thead><tr><th>You are told when…</th><th>What it gives you</th></tr></thead><tbody><tr><td>a period&#39;s report card is published</td><td>the link to your child&#39;s page</td></tr><tr><td>your child is marked absent without justification</td><td>the date and class, so you can justify it</td></tr><tr><td>your absence justification is accepted or refused</td><td>the decision, and the reason for a refusal</td></tr><tr><td>a discipline incident is recorded</td><td>the date and severity</td></tr><tr><td>a disciplinary council is convened, then once it decides</td><td>the session date, then the decision</td></tr><tr><td>your child is sent home by the infirmary</td><td>the reason and time of the visit</td></tr><tr><td>a payment is recorded</td><td>the amount and the remaining balance</td></tr></tbody></table><p>You are not told of every grade: the period&#39;s grades come with the report card, and averages can be checked any time on your child&#39;s page.</p><p>Account settings (password, notifications, language) work the same way for every role: see <a href="/era-guide/en/guide/prise-en-main.html">Getting started</a>.</p>',9)])])}const y=t(n,[["render",o]]);export{p as __pageData,y as default};
